  var pl=p();
  var pk=park();
  var date=st.日期||'——', week=st.星期||'——', time=st.时间||'——';
  var loc=pl.当前位置||'——';
  var stage=pk.当前阶段||'——';
  var progress=pk.剧情进度||1;
  var ending=pk.结局分支||'';
  var html='<div class="hd"><div class="hd-l">'
    +'<span class="hd-t">KK园区</span>'
    +'<span class="pill danger">'+esc(stage)+'</span>'
    +'<span class="pill">进度'+esc(progress)+'%</span>'
    +'<span class="pill gold">'+esc(date)+'</span>'
    +'<span class="pill">'+esc(week)+'</span>'
    +'<span class="pill safe">'+esc(time)+'</span>';
  if(ending){html+='<span class="pill danger">结局:'+esc(ending)+'</span>'}
  html+='<div class="hd-sub">📍 '+esc(loc)+'</div>'
    +'</div>'
    +'<button class="rfr'+(State.refreshing?' spinning':'')+'" data-act="refresh">🔄</button>'
    +'</div>';
  return html;
}

