    +'</div>';
  var buyers=pk.买家关注;
  if(buyers&&Array.isArray(buyers)&&buyers.length>0){
    body+='<div class="sect-title">买家关注 ('+buyers.length+')</div><div class="g">';
    for(var i=0;i<buyers.length;i++){body+=kv('买家'+(i+1),esc(buyers[i]))}
    body+='</div>';
