  body+='<div class="sect-title">派系关系 (-100~100)</div><div class="g">'
    +kv('园区董事会',pk.园区董事会)
    +kv('管理层',pk.管理层)
    +kv('打手团',pk.打手团)
    +kv('受害者群',pk.受害者群)
    +kv('暗网网络',pk.暗网网络)
