  var moralLabel=moral>50?'光明路线':(moral<-50?'黑暗路线':'中立');
  var moralCls=moral>50?'safe':(moral<-50?'danger':'');
  body+='<div class="sect-title">道德</div><div class="g2">'
    +kv('善恶值','<span class="'+moralCls+'">'+moral+'</span>')
    +kv('当前路线',moralLabel,moralCls)
    +'</div>';
  body+='<div class="sect-title">任务</div><div class="g2">'
    +kv('当前主线',pk.当前主线任务||'无','accent')
    +'</div>'
    +'<div class="sect-title">已接取支线 ('+arrCount(pk.已接取支线)+')</div>';
