  if(side&&Array.isArray(side)&&side.length>0){
    body+='<div class="g">';
    for(var i=0;i<side.length;i++){body+=kv('支线'+(i+1),esc(side[i]))}
    body+='</div>';
  }else{body+='<div class="empty-hint">无</div>'}
  body+='<div class="sect-title">已完成任务 ('+arrCount(pk.已完成任务)+')</div>';
  var done=pk.已完成任务;
  if(done&&Array.isArray(done)&&done.length>0){
    body+='<div class="g">';
    for(var i=0;i<done.length;i++){body+=kv('已完成'+(i+1),esc(done[i]),'safe')}
    body+='</div>';
  }else{body+='<div class="empty-hint">无</div>'}
  body+='<div class="sect-title">成就</div><div class="g2">'
    +kv('生存天数',num(pk.生存天数,0)+'天','safe')
    +kv('结识NPC',num(pk.结识NPC数,0))
    +kv('救助人数',num(pk.救助人数,0),'safe')
    +'</div>'
    +'<div class="sect-title">已达成 ('+arrCount(pk.已达成)+')</div>';
  var ach=pk.已达成;
  if(ach&&Array.isArray(ach)&&ach.length>0){
    body+='<div class="g">';
    for(var i=0;i<ach.length;i++){body+=kv('成就'+(i+1),esc(ach[i]),'safe')}
    body+='</div>';
  }else{body+='<div class="empty-hint">无</div>'}
