  body+='<div class="sect-title">成长记录</div><div class="g">'
    +kv('力量',grow.力量使用计数||0)+kv('敏捷',grow.敏捷使用计数||0)+kv('体质',grow.体质使用计数||0)
    +kv('智力',grow.智力使用计数||0)+kv('感知',grow.感知使用计数||0)+kv('魅力',grow.魅力使用计数||0)
