      html+='<div class="sect-title">重要事件 ('+sum.重要事件标记.length+')</div>';
      for(var ei=0;ei<sum.重要事件标记.length;ei++){
        html+='<div class="list-item">• '+esc(sum.重要事件标记[ei])+'</div>';
      }
    }
  }
  if(c.心情&&c.心情!=='—'){html+='<div class="list-item" style="border-left:3px solid var(--c-blue)">心情: '+esc(c.心情)+'</div>'}
  if(c.心声){html+='<div class="list-item" style="border-left:3px solid var(--c-warn)">心声: '+esc(c.心声)+'</div>'}
  if(c.当前状态){html+='<div class="list-item" style="border-left:3px solid var(--c-safe)">状态: '+esc(c.当前状态)+'</div>'}
  html+='</div></div>';
  return html;
}

