/* refresh */
function refresh(){
  if(State._refreshing)return;
  State._refreshing=true;State.refreshing=true;
  var stat=readStatData();
  if(hasData(stat)){State.stat=stat;State.loading=false}
  render();
  waitForReadableStat(8000,function(realStat){
    if(hasData(realStat)){State.stat=realStat;State.loading=false}
    State._refreshing=false;State.refreshing=false;
    render();requestStatFromBridge();
  });
}

/* 事件绑定 */
function bindEvents(){
  var root=document.getElementById('sb-root');
  root.addEventListener('toggle',function(e){
    var t=e.target;
    if(t&&t.tagName==='DETAILS'){var key=t.getAttribute('data-key');if(key){State.expanded[key]=t.hasAttribute('open')}}
  },true);
  root.addEventListener('click',function(e){
    var t=e.target.closest('[data-act]');
    if(!t)return;
    var act=t.getAttribute('data-act');
    if(act==='refresh'){refresh()}
    else if(act==='close-modal'){closeModal()}
    else if(act==='char-detail'){showCharDetail(t.getAttribute('data-id'))}
    else if(act==='npc-detail'){showNpcDetail(t.getAttribute('data-id'))}
    else if(act==='toggle-female'){
      var card=t.closest('.female-card');
      if(card){
        var fname=card.getAttribute('data-fname');
        if(card.className.indexOf('open')>=0){
          card.className=card.className.replace(/\\s*open\\s*/,' ').trim();
          if(fname)delete State.openFemaleCards[fname];
        }else{
          card.className=(card.className+' open').trim();
          if(fname)State.openFemaleCards[fname]=true;
        }
      }
    }
  });
  document.getElementById('modal-overlay').addEventListener('click',function(e){
    var t=e.target.closest('[data-act]');
    if(t&&t.getAttribute('data-act')==='close-modal'){closeModal()}
  });
}

/* 初始化 */
(function init(){
  bindEvents();
  var autoRefresh=function(){setTimeout(refresh,800)};
  try{if(typeof eventOn==='function'){eventOn('GENERATION_ENDED',autoRefresh);eventOn('MESSAGE_EDITED',autoRefresh);eventOn('mag_variable_update_ended',autoRefresh)}}catch(e){}
  try{var Mvu=getMvu();if(Mvu&&Mvu.events&&Mvu.events.VARIABLE_UPDATE_ENDED&&typeof eventOn==='function'){eventOn(Mvu.events.VARIABLE_UPDATE_ENDED,autoRefresh)}}catch(e){}
  window.addEventListener('message',function(e){
    try{
      var data=e.data;
      if(data&&data.type==='kk-mvu-stat-data'&&data.stat_data){
        var mesId=resolveMessageId();
        if(mesId>=0&&typeof data.messageId==='number'&&data.messageId>=0&&data.messageId!==mesId)return;
        if(hasMeaningfulStatData(data.stat_data)){
          cachedStatFromBridge=data.stat_data;
          cachedBridgeMessageId=typeof data.messageId==='number'?data.messageId:mesId;
          State.stat=deepMergeStat(DEFAULT_STAT,data.stat_data);
          State.loading=false;render();
        }
        return;
      }
      var t=(data&&data.type)||data||'';
      if(typeof t==='string'&&(t.indexOf('generation_ended')>=0||t.indexOf('message_edit')>=0))autoRefresh();
    }catch(x){}
  });
  var embedded=parseEmbeddedStat();
  if(embedded){cachedStatFromBridge=embedded;cachedBridgeMessageId=resolveMessageId()}
  requestStatFromBridge();refresh();
})();
</script>
